import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const q=JSON.parse('{"title":"03.5 软件维护 ★","description":"","frontmatter":{},"headers":[],"relativePath":"03-软件工程基础/05-软件维护.md","filePath":"03-软件工程基础/05-软件维护.md"}'),g={name:"03-软件工程基础/05-软件维护.md"};function a(e,t,d,u,l,h){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_03-5-软件维护-★" tabindex="-1">03.5 软件维护 ★ <a class="header-anchor" href="#_03-5-软件维护-★" aria-label="Permalink to &quot;03.5 软件维护 ★&quot;">​</a></h1><h3 id="_5-0-为什么维护才是成本大头" tabindex="-1">5.0 为什么维护才是成本大头 <a class="header-anchor" href="#_5-0-为什么维护才是成本大头" aria-label="Permalink to &quot;5.0 为什么维护才是成本大头&quot;">​</a></h3><p>维护是软件交付<strong>之后</strong>发生的修改。两条常考的&quot;反直觉&quot;结论：</p><ul><li><strong>软件维护期通常比开发期长得多，投入也大得多</strong>——所以&quot;如何降低维护成本&quot;其实比&quot;如何提高开发效率&quot;更值钱；</li><li><strong>可维护性是软件开发阶段（每一个时期）的关键目标</strong>——不是等要维护了才想起来，而是从需求、设计、编码时就要为可维护性做打算。</li></ul><p><strong>动机</strong>：既然 70% 以上的成本在维护，那么代码写得让人看不懂，就等于把成本推给了未来。</p><h3 id="_5-1-四类维护-必须对号入座" tabindex="-1">5.1 四类维护（必须对号入座） <a class="header-anchor" href="#_5-1-四类维护-必须对号入座" aria-label="Permalink to &quot;5.1 四类维护（必须对号入座）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>含义</th><th>场景识别</th><th>关键词抓手</th></tr></thead><tbody><tr><td><strong>改正性维护</strong>（更正性）</td><td>针对<strong>真实存在并且已经发生</strong>的错误，做诊断和改正</td><td>&quot;用户报告 bug&quot;&quot;统计结果算错了&quot;</td><td><strong>bug</strong></td></tr><tr><td><strong>适应性维护</strong></td><td>使软件<strong>适应信息技术变化和管理需求变化</strong></td><td>换操作系统、换数据库、接口规范改版</td><td><strong>第三方 / 环境变了</strong></td></tr><tr><td><strong>完善性维护</strong></td><td><strong>扩充功能、改善性能</strong>（增加系统分析设计阶段没规定的功能与性能特征）</td><td>&quot;希望增加微信通知功能&quot;&quot;查询要更快&quot;</td><td><strong>用户想要新的</strong></td></tr><tr><td><strong>预防性维护</strong></td><td>针对<strong>真实存在但还未发生</strong>的错误，<strong>主动</strong>为未来的修改与调整奠定更好基础</td><td>提前重构老代码、为将来的扩展预留结构</td><td><strong>程序员主动</strong></td></tr></tbody></table><p><strong>关键词区分（最省力的记法）</strong>：<strong>bug → 改正；用户（提新需求）→ 完善；第三方/环境 → 适应；程序员主动 → 预防</strong>。</p><h3 id="_5-2-反例演示-最易混的两对" tabindex="-1">5.2 反例演示（最易混的两对） <a class="header-anchor" href="#_5-2-反例演示-最易混的两对" aria-label="Permalink to &quot;5.2 反例演示（最易混的两对）&quot;">​</a></h3><ol><li><strong>改正 vs 预防</strong>：判别就一句话——<strong>错误发生了没</strong>。修<strong>已发生</strong>的报错 = 改正性；改<strong>还没发生</strong>的隐患（&quot;这段代码现在没错，但以后会出事，先重写&quot;）= 预防性。<strong>&quot;提前重构&quot;永远不是改正性。</strong></li><li><strong>完善 vs 适应</strong>：判别问一句——<strong>是&quot;自己想要更多&quot;还是&quot;外部逼着改&quot;</strong>。用户主动加功能 = 完善性；因为换了操作系统/数据库、外部接口改版而不得不改 = 适应性。<strong>&quot;升级到新 OS 后要改&quot;是适应性，不是完善性</strong>（完善性不涉及环境变化）。</li></ol><h3 id="_5-3-占比-直接考" tabindex="-1">5.3 占比（直接考） <a class="header-anchor" href="#_5-3-占比-直接考" aria-label="Permalink to &quot;5.3 占比（直接考）&quot;">​</a></h3><p><strong>完善性维护占全部维护工作量的 50%–60%，是最大的一块</strong>；<strong>预防性维护占比最小</strong>。所以&quot;软件维护工作量中占比最大的是&quot;→ 完善性维护。</p><h3 id="_5-4-可维护性的度量与评价指标" tabindex="-1">5.4 可维护性的度量与评价指标 <a class="header-anchor" href="#_5-4-可维护性的度量与评价指标" aria-label="Permalink to &quot;5.4 可维护性的度量与评价指标&quot;">​</a></h3><p><strong>先分清两个问题</strong>：本节说的<strong>可维护性</strong>，是“软件出了问题后，是否容易理解、定位、修改和验证”的质量属性；<strong>可维护度</strong>才是“在规定时间内修好的概率”，它依赖修复时间的统计模型。两者相关，但不能把一个固定公式当成所有题目的通用定义。</p><p><strong>稳定判断</strong>：<strong>MTTR 是平均修复时间</strong>，在其他条件相近时，<strong>MTTR 越小，越容易维护</strong>。例如同样的故障，系统 A 平均 1 小时修复、系统 B 平均 5 小时修复；A 的修复效率更好，因而可维护性更高。</p><p>若题面<strong>明确</strong>把时间按某个基准单位归一化，并定义“可维护性指标”为 <code>1 / (1 + MTTR)</code>，才按该定义计算；它只是题设给出的评分指标，不是普遍适用的质量模型。规定时间内修好的概率、MTTR 与可用性的严格口径见<a href="/ruankao/09-计算机系统基础/06-流水线与可靠性.html">第 09 课「流水线与可靠性」</a>。反例：看到 MTTR 就直接把 <code>1 / (1 + MTTR)</code> 当成可维护度——错；题目问“4 小时内修好的概率”时，应根据修复率模型计算，而不是套归一化评分式。</p><p><strong>三个定性评价指标（记这三个，别多别少）</strong>：<strong>可理解性、可测试性、可修改性</strong>。考题会用&quot;一致性&quot;来当干扰项——它不是可维护性的评价指标。</p><p><strong>维护工具六类</strong>（认名字即可）：版本控制工具、文档分析工具、开发信息库工具、<strong>逆向工程工具</strong>、<strong>再工程工具</strong>、配置管理支持工具。</p><p><strong>逆向工程 vs 再工程</strong>（各一句）：<strong>逆向工程</strong> = 从代码<strong>反推</strong>出设计甚至需求（由底层往上还原）；<strong>再工程</strong> = 在逆向工程的基础上<strong>重构改造</strong>，得到一个新的改进版本（比逆向工程多&quot;改造&quot;这一步）。</p><h3 id="_5-5-应试动作" tabindex="-1">5.5 应试动作 <a class="header-anchor" href="#_5-5-应试动作" aria-label="Permalink to &quot;5.5 应试动作&quot;">​</a></h3><p>背三件事：① 四类维护 + 四个关键词抓手；② <strong>完善性维护占大头（过半）</strong>、预防性维护最小；③ 可维护性盯 <strong>MTTR</strong>，评价指标是<strong>可理解性、可测试性、可修改性</strong>三件套。做题先问&quot;错误发生了没&quot;，再问&quot;自己想要还是环境逼的&quot;。</p>',21)])])}const _=o(g,[["render",a]]);export{q as __pageData,_ as default};
